#!/usr/bin/env bash
set -e
export DEBIAN_FRONTEND=noninteractive

echo -e "\n\e[34m[1/6] 🔄 Updating package repositories & installing system utilities...\e[0m"
apt-get update -y
apt-get purge -y libnode-dev libnode72 2>/dev/null || true
apt-get install -y --no-install-recommends \
    curl wget git unzip zip tar xz-utils tmux htop jq ufw build-essential \
    ca-certificates gnupg lsb-release software-properties-common

echo -e "\n\e[34m[2/6] 🟢 Installing Node.js 20 LTS + PM2 + JS Tools...\e[0m"
apt-get purge -y nodejs npm libnode-dev libnode72 2>/dev/null || true
curl -fsSL https://deb.nodesource.com/setup_20.x | bash - 2>/dev/null || true
apt-get install -y nodejs 2>/dev/null || true

# Fallback: install official standalone Node.js 20 LTS binary if repo installation failed
if ! command -v node &> /dev/null || ! command -v npm &> /dev/null; then
    echo -e "\e[33m⚠️ NodeSource repo install bypassed; installing official standalone Node 20 LTS binary...\e[0m"
    ARCH=$(uname -m)
    if [ "$ARCH" = "x86_64" ]; then NODE_ARCH="x64"; elif [ "$ARCH" = "aarch64" ]; then NODE_ARCH="arm64"; else NODE_ARCH="x64"; fi
    NODE_VER="v20.18.0"
    (curl -fsSL --connect-timeout 15 "https://nodejs.org/dist/${NODE_VER}/node-${NODE_VER}-linux-${NODE_ARCH}.tar.xz" -o /tmp/node20.tar.xz || \
     curl -fsSL --connect-timeout 15 "https://npmmirror.com/mirrors/node/${NODE_VER}/node-${NODE_VER}-linux-${NODE_ARCH}.tar.xz" -o /tmp/node20.tar.xz) 2>/dev/null || true
    
    if [ -f /tmp/node20.tar.xz ]; then
        tar -xJf /tmp/node20.tar.xz -C /usr/local --strip-components=1
        rm -f /tmp/node20.tar.xz
    fi
fi

export PATH="/usr/local/bin:/usr/bin:$PATH"

if command -v npm &> /dev/null; then
    echo -e "\e[32m✓ Node.js ($(node -v)) & npm ($(npm -v)) successfully installed.\e[0m"
    npm install -g pm2 yarn pnpm nodemon 2>/dev/null || true
    pm2 startup systemd -u root --hp /root 2>/dev/null || true
else
    echo -e "\e[31m✗ Warning: npm is not available in PATH.\e[0m"
fi

echo -e "\n\e[34m[3/6] 🌐 Installing Headless Browser dependencies (Puppeteer / Playwright / Cloudflare Bypass)...\e[0m"
apt-get install -y \
    libnss3 libatk1.0-0 libatk-bridge2.0-0 libcups2 libdrm2 libxkbcommon0 \
    libxcomposite1 libxdamage1 libxfixes3 libxrandr2 libgbm1 libasound2 \
    libpango-1.0-0 libcairo2 libx11-xcb1 libxcb-dri3-0 libxshmfence1 \
    fonts-liberation fonts-noto-color-emoji fonts-dejavu-core fonts-freefont-ttf 2>/dev/null || true

echo -e "\n\e[34m[4/6] 🐍 Installing Python 3 + Pip + Scraping & Web Libraries...\e[0m"
apt-get install -y python3 python3-pip python3-venv python3-dev 2>/dev/null || true
PIP_BREAK="--break-system-packages"
python3 -m pip install --upgrade pip $PIP_BREAK 2>/dev/null || python3 -m pip install --upgrade pip 2>/dev/null || true

python3 -m pip install $PIP_BREAK \
    requests curl_cffi cloudscraper undetected-chromedriver \
    playwright selenium beautifulsoup4 lxml aiohttp httpx \
    fastapi uvicorn python-dotenv fake-useragent tqdm pandas psutil 2>/dev/null || \
python3 -m pip install \
    requests curl_cffi cloudscraper undetected-chromedriver \
    playwright selenium beautifulsoup4 lxml aiohttp httpx \
    fastapi uvicorn python-dotenv fake-useragent tqdm pandas psutil 2>/dev/null || true

echo -e "\n\e[34m[5/6] 🛡️ Installing Apache2 + Native PHP Module (Rock-solid & Zero Socket Failures)...\e[0m"
systemctl stop nginx 2>/dev/null || true
systemctl disable nginx 2>/dev/null || true

apt-get install -y apache2 libapache2-mod-php php php-cli php-curl php-json php-mbstring php-xml php-zip php-bcmath php-intl php-sqlite3 2>/dev/null || true
a2enmod rewrite 2>/dev/null || true
a2enmod php* 2>/dev/null || true

# Configure Apache DirectoryIndex to prioritize index.php
echo "DirectoryIndex index.php index.html" > /etc/apache2/mods-available/dir.conf 2>/dev/null || true

systemctl enable apache2 2>/dev/null || true
systemctl restart apache2 2>/dev/null || true

echo -e "\n\e[34m[6/6] 🔐 Configuring passwordless sudo for WebConsole (www-data)...\e[0m"
echo "www-data ALL=(ALL) NOPASSWD: ALL" > /etc/sudoers.d/99-webconsole-nopasswd
chmod 0440 /etc/sudoers.d/99-webconsole-nopasswd

mkdir -p /var/www/html

echo -e "\n\e[34m📦 Installing WebConsole Pro v1.6.0...\e[0m"
if ! curl -fsSL --connect-timeout 10 https://raw.githubusercontent.com/fazilatma/new/main/webconsole.php -o /var/www/html/webconsole.php 2>/dev/null; then
    echo -e "\e[33mExtracting built-in WebConsole package...\e[0m"
    cat << 'WCP_FALLBACK' | base64 -d | gzip -d > /var/www/html/webconsole.php

WCP_FALLBACK
fi

cp /var/www/html/webconsole.php /var/www/html/index.php
rm -f /var/www/html/index.html 2>/dev/null || true
chown -R www-data:www-data /var/www/html
chmod -R 775 /var/www/html
usermod -a -G www-data root 2>/dev/null || true

# Robust Public IP detection with regex verification
get_public_ip() {
    local ip=""
    for provider in "https://api.ipify.org" "https://icanhazip.com" "https://ifconfig.io" "https://checkip.amazonaws.com"; do
        ip=$(curl -s -4 --connect-timeout 3 "$provider" 2>/dev/null | tr -d '[:space:]' || echo "")
        if echo "$ip" | grep -Eq '^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$'; then
            echo "$ip"
            return 0
        fi
    done
    hostname -I 2>/dev/null | awk '{print $1}' | tr -d '[:space:]'
}

SERVER_IP=$(get_public_ip)
NODE_VER_DISP=$(node -v 2>/dev/null || echo 'Not found')
NPM_VER_DISP=$(npm -v 2>/dev/null || echo 'Not found')
PM2_VER_DISP=$(pm2 -v 2>/dev/null | tail -n 1 || echo 'Not found')
PY_VER_DISP=$(python3 --version 2>/dev/null || echo 'Not found')
PHP_VER_DISP=$(php -r 'echo PHP_VERSION;' 2>/dev/null || echo 'Not found')

echo -e "\n\e[32m========================================================\e[0m"
echo -e "\e[32m🎉 WebConsole Pro & Apache2 Server Setup Completed!\e[0m"
echo -e "\e[32m========================================================\e[0m"
echo -e "🔹 Web Server:    \e[32mApache2 (with native libapache2-mod-php)\e[0m"
echo -e "🔹 Node.js:       \e[33m${NODE_VER_DISP}\e[0m (npm ${NPM_VER_DISP})"
echo -e "🔹 PM2:           \e[33m${PM2_VER_DISP}\e[0m"
echo -e "🔹 Python:        \e[33m${PY_VER_DISP}\e[0m"
echo -e "🔹 PHP:           \e[33m${PHP_VER_DISP}\e[0m"
echo -e "🔹 WebConsole:    \e[32mv1.6.0 deployed (/var/www/html/webconsole.php)\e[0m"
echo -e "🔹 NOPASSWD:      \e[32mEnabled for user www-data\e[0m"
echo -e "🔹 Web URL:       \e[36mhttp://${SERVER_IP}/\e[0m"
echo -e "\e[32m========================================================\e[0m\n"
